<?php function top(string $title):void{$u=me();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · Entre Páginas</title><link rel="stylesheet" href="assets/style.css"></head><body><header><a class="brand" href="index.php"><span>♧</span> Entre Páginas</a><form action="index.php" method="get" class="search"><input name="q" placeholder="Buscar libros, personas o clubes" style="border:0;background:transparent;width:100%"></form><div><?php if($u):?><a href="perfil.php">@<?=e($u['usuario'])?></a> · <a href="logout.php">Salir</a><?php else:?><a href="login.php">Entrar</a> · <a href="registro.php">Registrarse</a><?php endif;?></div></header><?php }function sidebar():void{$u=me();?><aside class="left"><div class="card"><?php if($u):?><div class="profile"><div class="avatar big"><?=e(mb_substr($u['nombre'],0,1))?></div><div><h3><?=e($u['nombre'])?></h3><span class="muted">@<?=e($u['usuario'])?></span></div></div><p><a class="btn secondary" href="perfil.php">Ver mi perfil →</a></p><?php else:?><h3>Tu comunidad lectora</h3><a class="btn" href="registro.php">Únete ahora</a><?php endif;?></div><div class="card nav"><a href="index.php">⌂ &nbsp; Inicio</a><a href="biblioteca.php">▤ &nbsp; Mi biblioteca</a><a href="clubes.php">♧ &nbsp; Clubes de lectura</a><a href="guardados.php">♧ &nbsp; Guardados</a><a href="perfil.php">♙ &nbsp; Mi perfil</a><a class="btn" style="color:#fff;text-align:center;margin-top:15px" href="publicar.php">✎ Crear publicación</a></div></aside><?php }function rightbar():void{?><aside class="right"><div class="card"><h2>Lectura del mes</h2><h3>El principito</h3><p class="muted">Antoine de Saint-Exupéry</p><p>Una historia atemporal sobre la amistad y lo esencial.</p><a class="btn" href="clubes.php">Unirme a la conversación</a></div><div class="card"><h2>Clubes para descubrir</h2><?php foreach(db()->query('SELECT id,nombre,descripcion FROM clubes ORDER BY id DESC LIMIT 3') as $c):?><p><a href="club.php?id=<?=$c['id']?>"><strong><?=e($c['nombre'])?></strong></a><br><span class="muted"><?=e(mb_strimwidth($c['descripcion']??'',0,85,'…'))?></span></p><?php endforeach;?><a href="clubes.php">Ver todos →</a></div><div class="card"><h2>Tu reto lector</h2><?php $u=me();if($u){$s=db()->prepare("SELECT COUNT(*) FROM bibliotecas WHERE usuario_id=? AND estado='terminado'");$s->execute([$u['id']]);$n=$s->fetchColumn();$r=db()->prepare('SELECT meta FROM retos WHERE usuario_id=? AND anio=YEAR(CURDATE())');$r->execute([$u['id']]);$meta=$r->fetchColumn()?:12;echo '<strong>'.e($n).' de '.e($meta).' libros</strong><p><progress value="'.min($n,$meta).'" max="'.e($meta).'" style="width:100%"></progress></p>';}else echo '<p>Inicia sesión para seguir tu progreso.</p>';?></div></aside><?php }function bottom():void{echo '</body></html>';}